// Offline / pre-recorded cache: demo/offline-cache.json (generated by `npm run build:demo`).
// Each entry = a known test image fingerprint + complete AnalyzeResponse per language.
import { readFileSync, existsSync } from 'node:fs';
import { hamming } from './imagehash.js';

export function loadOfflineCache(file, log) {
  if (!existsSync(file)) return { entries: [] };
  try {
    const data = JSON.parse(readFileSync(file, 'utf8'));
    return { entries: Array.isArray(data.entries) ? data.entries : [] };
  } catch (err) {
    log?.warn({ msg: 'offline cache unreadable; offline fallback disabled', error: err.message });
    return { entries: [] };
  }
}

/**
 * Exact sha256 match first, else the closest dhash within maxDistance, but only when it is
 * unambiguous (at least 2 bits closer than the runner-up). A wrong building on stage is worse
 * than no match.
 */
export function matchImage(cache, fp, maxDistance) {
  if (!fp) return null;
  const exact = cache.entries.find((e) => e.sha256 === fp.sha256);
  if (exact) return { entry: exact, distance: 0, how: 'sha256' };
  if (!fp.dhash) return null;
  const ranked = cache.entries
    .filter((e) => e.dhash)
    .map((e) => ({ entry: e, distance: hamming(fp.dhash, e.dhash), how: 'dhash' }))
    .sort((a, b) => a.distance - b.distance);
  const [best, second] = ranked;
  if (!best || best.distance > maxDistance) return null;
  if (second && second.distance - best.distance < 2) return null;
  return best;
}

/** For /narrate in offline mode: find a cached response with the same style + detail labels. */
export function matchNarration(cache, { style, details }) {
  const sig = (ds) => ds.map((d) => `${d.type}:${d.label}`).sort().join('|');
  const want = sig(details);
  return cache.entries.find((e) => {
    const r = e.responses?.en ?? e.responses?.ro;
    return r && r.style === style && sig(r.details) === want;
  }) ?? null;
}

export function cachedAnalyze(entry, lang) {
  const body = entry.responses?.[lang] ?? entry.responses?.en ?? entry.responses?.ro;
  return body ? structuredClone(body) : null;
}
